#include <bits/stdc++.h>
using namespace std;

class Solver {
public:
    static const int MAXT = 65;
    static const int MAXC = 12;
    static const int MAXN = 25;
    static const int INF = 10007;

    int n, k;
    string S[MAXN], T[MAXN];
    int distToZ[MAXN][MAXN];
    int dp[MAXT][MAXC][MAXC][MAXC][MAXC];
    int dx[4] = {1, 0, -1, 0};
    int dy[4] = {0, 1, 0, -1};
    vector<pair<int,int>> src, snk;

    struct PushRelabelFIFO {
        struct Edge { int from, to, cap, flow; };
        int n;
        vector<Edge> edges;
        vector<vector<int>> adj;
        vector<int> h, excess, inq;
        queue<int> q;

        PushRelabelFIFO(int n) : n(n), adj(n), h(n), excess(n), inq(n) {}

        void addEdge(int u, int v, int cap) {
            adj[u].push_back(edges.size());
            edges.push_back({u, v, cap, 0});
            adj[v].push_back(edges.size());
            edges.push_back({v, u, 0, 0});
        }

        void enqueue(int u) {
            if (!inq[u] && excess[u] > 0) {
                q.push(u);
                inq[u] = 1;
            }
        }

        void push(int id) {
            Edge &e = edges[id];
            int d = min(e.cap - e.flow, excess[e.from]);
            if (d > 0 && h[e.from] == h[e.to] + 1) {
                e.flow += d;
                excess[e.to] += d;
                excess[e.from] -= d;
                edges[id ^ 1].flow -= d;
                enqueue(e.to);
            }
        }

        void relabel(int u) {
            int minH = 2 * n;
            for (int id : adj[u]) {
                const Edge &e = edges[id];
                if (e.cap > e.flow) minH = min(minH, h[e.to]);
            }
            h[u] = minH + 1;
        }

        void discharge(int u) {
            while (excess[u] > 0) {
                bool pushed = false;
                for (int id : adj[u]) {
                    Edge &e = edges[id];
                    if (e.cap > e.flow && h[u] == h[e.to] + 1) {
                        push(id);
                        pushed = true;
                        break;
                    }
                }
                if (!pushed) relabel(u);
            }
        }

        int maxFlow(int s, int t) {
            h[s] = n;
            inq[s] = inq[t] = 1;
            for (int id : adj[s]) {
                Edge &e = edges[id];
                if (e.cap > 0) {
                    int d = e.cap;
                    e.flow += d;
                    edges[id ^ 1].flow -= d;
                    excess[e.to] += d;
                    excess[s] -= d;
                    enqueue(e.to);
                }
            }
            while (!q.empty()) {
                int u = q.front();
                q.pop();
                inq[u] = 0;
                discharge(u);
                if (excess[u] > 0) enqueue(u);
            }
            return excess[t];
        }
    };

    void readInput() {
        cin >> n >> k;
        for (int i = 0; i < n; ++i) cin >> S[i];
        for (int i = 0; i < n; ++i) cin >> T[i];
        memset(dp, -1, sizeof dp);
    }

    void bfsFromZ(int sx, int sy) {
        memset(distToZ, -1, sizeof distToZ);
        queue<pair<int,int>> q;
        distToZ[sx][sy] = 0;
        q.push({sx, sy});
        while (!q.empty()) {
            auto [x, y] = q.front();
            q.pop();
            for (int d = 0; d < 4; ++d) {
                int nx = x + dx[d];
                int ny = y + dy[d];
                if (nx < 0 || nx >= n || ny < 0 || ny >= n) continue;
                if (distToZ[nx][ny] != -1) continue;
                if (T[nx][ny] == 'Y' || T[nx][ny] == 'Z') continue;
                distToZ[nx][ny] = distToZ[x][y] + 1;
                q.push({nx, ny});
            }
        }
    }

    int canReach(int t, int x0, int y0, int x, int y) {
        if (distToZ[x0][y0] < t) return 0;
        if (x0 == x && y0 == y) return 1;
        if (t >= k) return 0;
        if (distToZ[x0][y0] <= t) return 0;
        int &res = dp[t][x0][y0][x][y];
        if (res != -1) return res;
        for (int d = 0; d < 4; ++d) {
            int nx = x0 + dx[d];
            int ny = y0 + dy[d];
            if (nx < 0 || nx >= n || ny < 0 || ny >= n) continue;
            if (S[nx][ny] == 'Y' || S[nx][ny] == 'Z') continue;
            if (canReach(t + 1, nx, ny, x, y)) return res = 1;
        }
        return res = 0;
    }

    void collect() {
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j) {
                char c = S[i][j];
                if (c != 'Z' && c != 'Y' && c != '0') src.push_back({i, j});
            }
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j) {
                char c = T[i][j];
                if (c != 'Z' && c != 'Y' && c != '0') snk.push_back({i, j});
            }
    }

    int run() {
        readInput();

        int zx = -1, zy = -1;
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                if (T[i][j] == 'Z') zx = i, zy = j;

        bfsFromZ(zx, zy);

        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                if (distToZ[i][j] == -1) distToZ[i][j] = INF;

        collect();

        int S = 0;
        int TT = (int)src.size() + (int)snk.size() + 1;
        PushRelabelFIFO flow(TT + 1);

        for (int i = 0; i < (int)src.size(); ++i)
            flow.addEdge(S, i + 1, S[src[i].first][src[i].second] - '0');

        for (int i = 0; i < (int)snk.size(); ++i)
            flow.addEdge((int)src.size() + i + 1, TT,
                         T[snk[i].first][snk[i].second] - '0');

        for (int i = 0; i < (int)src.size(); ++i)
            for (int j = 0; j < (int)snk.size(); ++j)
                if (canReach(0, src[i].first, src[i].second,
                             snk[j].first, snk[j].second))
                    flow.addEdge(i + 1, (int)src.size() + j + 1, INF);

        return flow.maxFlow(S, TT);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    Solver solver;
    cout << solver.run() << '\n';
    return 0;
}
